//! Contracts of the read-out indicators (plan 141), from `tests/fixtures/contract_readouts.txt`
//! (generated by `reference/kestrel_reference/fixtures/contract_readouts.py`).
//!
//! Every case runs through `build_checked`, so `values` covers the f64 registry surface.

use super::{assert_holds, assert_rejected, Coverage};
use crate::common::contract::{load, ContractCase};
use kestrel_chartkit::IndicatorUnit;

const FIXTURE: &str = include_str!("../fixtures/contract_readouts.txt");

fn case(name: &str, indicator: &str, unit: IndicatorUnit) -> ContractCase {
    load(FIXTURE, name, indicator, unit)
}

/// Indicators of this family whose contract is not yet written. Moved into [`COVERAGE`] once
/// their cases exist; a name in neither list fails the matrix.
pub const PENDING: &[&str] = &[];

pub const COVERAGE: &[Coverage] = &[Coverage::full("fractal_dimension")];

// --- Fractal dimension -----------------------------------------------------------------------

#[test]
fn fractal_dimension_defaults() {
    assert_holds(&case(
        "fractal_dimension_defaults",
        "fractal_dimension",
        IndicatorUnit::Unitless,
    ));
}

