#[test]
fn fractal_dimension_rejects_invalid_configuration() {
    assert_rejected("fractal_dimension", &[("period", 3.0)]);
    assert_rejected("fractal_dimension", &[("period", 10.5)]);
    assert_rejected("fractal_dimension", &[("period", 10001.0)]);
    assert_rejected("fractal_dimension", &[("method", 2.0)]);
    assert_rejected("fractal_dimension", &[("len", 30.0)]);
}
